use crate::{scene::{Scene,ObjectId},renderer::Renderer,viewport::Viewport};
use std::rc::Rc;
fn scene(depth:f64,kind:u8,sloped:bool)->(Scene,ObjectId,ObjectId){
 let mut scene=Scene::empty();let points=if sloped{[[-0.8,-0.8,0.1],[0.8,-0.8,0.1],[0.,0.8,0.9]]}else{[[-0.8,-0.8,0.5],[0.8,-0.8,0.5],[0.,0.8,0.5]]};let solid=scene.insert(crate::prepared::PreparedMesh::triangle(points,[0.1,0.5,0.8]).unwrap()).unwrap();let color=session_rust::Color::new(1.,0.,0.,1.);
 let ink=if kind==2{let mut p=session_rust::Point::new(0.,0.,depth);p.width=10.;p.pointcolor=color;scene.insert_point(crate::marker::PreparedPoint::new(Rc::new(p)).unwrap()).unwrap()}else{let mut line=session_rust::Line::new(-0.25,0.,depth,0.25,0.,depth);line.width=4.;line.linecolor=color;if kind==1{line.arrowhead=session_rust::Arrowhead::END;scene.insert_path(crate::chain::PreparedChain::line(Rc::new(line)).unwrap()).unwrap()}else{scene.insert_line(crate::stroke::PreparedLine::new(Rc::new(line)).unwrap()).unwrap()}};(scene,solid,ink)
}
fn renderer(scene:&Scene,size:[u32;2],density:f32)->Renderer{renderer_limit(scene,size,density,None)}
fn renderer_limit(scene:&Scene,size:[u32;2],density:f32,storage:Option<u64>)->Renderer{let instance=wgpu::Instance::new(wgpu::InstanceDescriptor{backends:wgpu::Backends::VULKAN,flags:Default::default(),memory_budget_thresholds:Default::default(),backend_options:Default::default(),display:None});let adapter=pollster::block_on(instance.request_adapter(&Default::default())).unwrap();let mut descriptor=wgpu::DeviceDescriptor::default();if let Some(bytes)=storage{descriptor.required_limits.max_storage_buffer_binding_size=bytes;}let(device,queue)=pollster::block_on(adapter.request_device(&descriptor)).unwrap();device.on_uncaptured_error(std::sync::Arc::new(|error|panic!("actual finite visibility: {error}")));let mut renderer=Renderer::new(device,queue,wgpu::TextureFormat::Rgba8Unorm,scene);renderer.resize(Viewport{width:size[0],height:size[1]});renderer.set_density(density);renderer}
fn wait(renderer:&Renderer){renderer.device.poll(wgpu::PollType::Wait{submission_index:None,timeout:Some(std::time::Duration::from_secs(5))}).unwrap();}
fn red_pixels(renderer:&Renderer,size:[u32;2])->usize{red_frame(renderer,size,session_rust::Xform::identity().m.map(|v|v as f32))}
fn red_frame(renderer:&Renderer,size:[u32;2],matrix:[f32;16])->usize{let texture=renderer.device.create_texture(&wgpu::TextureDescriptor{label:Some("finite visibility pixels"),size:wgpu::Extent3d{width:size[0],height:size[1],depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});renderer.draw(&texture.create_view(&Default::default()),&Default::default(),&matrix);let pitch=(size[0]*4).div_ceil(256)*256;let read=renderer.device.create_buffer(&wgpu::BufferDescriptor{label:None,size:u64::from(pitch)*u64::from(size[1]),usage:wgpu::BufferUsages::MAP_READ|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});let mut encoder=renderer.device.create_command_encoder(&Default::default());encoder.copy_texture_to_buffer(texture.as_image_copy(),wgpu::TexelCopyBufferInfo{buffer:&read,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(pitch),rows_per_image:Some(size[1])}},texture.size());renderer.queue.submit([encoder.finish()]);let(tx,rx)=std::sync::mpsc::channel();read.slice(..).map_async(wgpu::MapMode::Read,move|r|tx.send(r).unwrap());wait(renderer);rx.recv().unwrap().unwrap();let bytes=read.slice(..).get_mapped_range();let count=bytes.chunks_exact(pitch as usize).flat_map(|row|row[..size[0]as usize*4].chunks_exact(4)).filter(|p|p[0]>200&&p[1]<50&&p[2]<50).count();drop(bytes);read.unmap();count}
fn picked(renderer:&mut Renderer,at:[f32;2])->Option<[u32;2]>{pick_frame(renderer,at,session_rust::Xform::identity().m.map(|v|v as f32))}
fn pick_frame(renderer:&mut Renderer,at:[f32;2],matrix:[f32;16])->Option<[u32;2]>{renderer.request_pick(at,matrix).unwrap();wait(renderer);renderer.take_pick(matrix).unwrap().unwrap()}

#[test]
fn actual_original_mesh_color_and_face_picks_share_the_world_cut_before_any_color_frame(){
 let mut scene=Scene::empty();let solid=scene.insert(crate::prepared::PreparedMesh::triangle([[-0.8,-0.8,0.5],[0.8,-0.8,0.5],[0.,0.8,0.5]],[1.,0.,0.]).unwrap()).unwrap();let size=[320,240];let mut renderer=renderer(&scene,size,1.);let plane=crate::clipping_geometry::plane_from(crate::clipping_geometry::Mode::Yz,&[[0.,0.,0.5]],0.9).unwrap();crate::plane_original::insert(&mut scene,Rc::new(plane)).unwrap();renderer.set_scene(&scene,None);
 assert_eq!(picked(&mut renderer,[-0.3,0.]),Some([solid.value(),0]));assert_eq!(picked(&mut renderer,[0.3,0.]),None,"the cut side has no original mesh pick before color rendering");let cut=red_pixels(&renderer,size);renderer.set_pick_mode(crate::pick_sources::Mode::Face);let kept=picked(&mut renderer,[-0.3,0.]).unwrap();assert_eq!(kept[0],solid.value());assert!(kept[1]>0);assert_eq!(picked(&mut renderer,[0.3,0.]),None);
 renderer.set_clipping(false,true);let full=red_pixels(&renderer,size);assert!(cut>full/3&&cut<full*2/3,"actual half-space color with the same visible plane: {cut}/{full}");assert_eq!(picked(&mut renderer,[0.3,0.]).unwrap()[0],solid.value());let before=renderer.clipping_usage();red_pixels(&renderer,size);assert_eq!(renderer.clipping_usage(),before,"unchanged clipping uniforms stay cached");
}
fn cut_x(scene:&mut Scene)->ObjectId{let p=crate::clipping_geometry::plane_from(crate::clipping_geometry::Mode::Yz,&[[0.,0.,0.5]],0.9).unwrap();crate::plane_original::insert(scene,Rc::new(p)).unwrap()}
#[test]
fn clipping_all_original_ink_families_preserve_kept_integer_owners_and_release_cut_occluders(){
 for kind in 0..3{let mut scene=Scene::empty();let red=session_rust::Color::new(1.,0.,0.,1.);let owner=if kind==2{let mut p=session_rust::Point::new(-0.3,0.,0.3);p.width=16.;p.pointcolor=red.clone();let id=scene.insert_point(crate::marker::PreparedPoint::new(Rc::new(p)).unwrap()).unwrap();p=session_rust::Point::new(0.3,0.,0.3);p.width=16.;p.pointcolor=red;scene.insert_point(crate::marker::PreparedPoint::new(Rc::new(p)).unwrap()).unwrap();id}else{let mut line=session_rust::Line::new(-0.6,0.,0.3,0.6,0.,0.3);line.width=8.;line.linecolor=red;if kind==1{line.arrowhead=session_rust::Arrowhead::END;scene.insert_path(crate::chain::PreparedChain::line(Rc::new(line)).unwrap()).unwrap()}else{scene.insert_line(crate::stroke::PreparedLine::new(Rc::new(line)).unwrap()).unwrap()}};cut_x(&mut scene);for density in [1.,2.]{let mut r=renderer(&scene,[320,240],density);assert_eq!(picked(&mut r,[-0.3,0.]).unwrap()[0],owner.value(),"kept kind{kind}");assert_eq!(picked(&mut r,[0.3,0.]),None,"cut kind{kind}");let cut=red_pixels(&r,[320,240]);r.set_clipping(false,true);let full=red_pixels(&r,[320,240]);assert!(cut>0&&cut<full*3/4,"kind{kind} density{density} color {cut}/{full}");}}
 let(mut scene,_,ink)=scene(0.7,0,false);let p=crate::clipping_geometry::plane_from(crate::clipping_geometry::Mode::Xy,&[[0.,0.,0.6]],0.9).unwrap();let p=crate::clipping_geometry::flipped(&p);crate::plane_original::insert(&mut scene,Rc::new(p)).unwrap();let mut r=renderer(&scene,[320,240],1.);assert_eq!(picked(&mut r,[-0.18,0.]).unwrap()[0],ink.value());assert!(red_pixels(&r,[320,240])>100,"a cut solid must not keep occluding the retained original ink");
}
#[test]
fn clipping_cloud_cache_color_and_original_u32_picks_follow_on_off_before_color(){
 let mut original=session_rust::PointCloud::from_coords(vec![-0.3,0.,0.3,0.3,0.,0.3],vec![255,0,0,255,255,0,0,255],vec![]).to_proto();original.point_size=16.;original.point_ids=vec![u32::MAX,16_777_217];let source=Rc::new(session_rust::PointCloud::from_proto(original.clone()));let _=source.guid();original=source.to_proto();let mut scene=Scene::empty();let owner=scene.insert_cloud(crate::cloud::Prepared::new(source.clone()).unwrap()).unwrap();cut_x(&mut scene);let mut r=renderer(&scene,[320,240],1.);assert_eq!(picked(&mut r,[-0.3,0.]),Some([owner.value(),0]));assert_eq!(picked(&mut r,[0.3,0.]),None);let cut=red_pixels(&r,[320,240]);let usage=r.cloud_usage();red_pixels(&r,[320,240]);assert_eq!(r.cloud_usage()[3],usage[3],"unchanged clip uniform retains actual cached discs");r.set_clipping(false,true);assert_eq!(picked(&mut r,[0.3,0.]),Some([owner.value(),0]));let full=red_pixels(&r,[320,240]);assert!(cut>0&&cut<full*3/4,"cloud {cut}/{full}");assert_eq!(r.cloud_usage()[2],usage[2],"changing clipping does not upload original columns");assert_eq!(source.to_proto(),original);
}
#[test]
fn clipping_sheet_centerline_color_and_crop_ids_preserve_original_source_entities(){
 let original=session_rust::proto::Sheet{guid:crate::sheet_example::source().guid,coords:vec![-0.6,0.,0.3,0.6,0.,0.3],colors:vec![0xff00_00ff],widths:vec![0.035],source_ids:vec![16_777_217],segment_count:1,entity_count:16_777_218,..Default::default()};let mut scene=Scene::empty();let owner=scene.insert_sheet(Rc::new(crate::sheet_source::Prepared::new(Rc::new(original.clone())).unwrap())).unwrap();cut_x(&mut scene);let mut r=renderer(&scene,[320,240],1.);assert_eq!(picked(&mut r,[-0.3,0.]).unwrap()[0],owner.value());assert_eq!(picked(&mut r,[0.3,0.]),None);let cut=red_pixels(&r,[320,240]);let uploads=r.sheet_usage()[3];r.set_clipping(false,true);assert_eq!(picked(&mut r,[0.3,0.]).unwrap()[0],owner.value());let full=red_pixels(&r,[320,240]);assert!(cut>0&&cut<full*3/4,"sheet {cut}/{full}");assert_eq!(r.sheet_usage()[3],uploads);assert_eq!(*scene.sheets()[0].prepared.original,original);
}
#[test]
fn clipping_text_uses_the_sixth_original_world_plane_for_color_and_nameplate_picks(){
 use crate::{scene_label::{Prepared,example},text::TextPlacement};let mut scene=Scene::empty();let mut source=example(TextPlacement::Nameplate{world:[0.3,0.,0.3],padding:[20.,12.],rounded:true});source.label.text="Hi".into();let owner=scene.insert_text(Prepared::new(Rc::new(source)).unwrap()).unwrap();for _ in 0..5{let p=crate::clipping_geometry::plane_from(crate::clipping_geometry::Mode::Yz,&[[0.9,0.,0.5]],0.2).unwrap();crate::plane_original::insert(&mut scene,Rc::new(p)).unwrap();}cut_x(&mut scene);let mut r=renderer(&scene,[320,240],1.);assert_eq!(picked(&mut r,[0.3,0.]),None);red_pixels(&r,[320,240]);assert_eq!(r.text_error(),None);assert_eq!(r.text_stats().unwrap().requested_glyphs,0);r.set_clipping(false,true);assert_eq!(picked(&mut r,[0.3,0.]),Some([owner.value(),0]));red_pixels(&r,[320,240]);assert_eq!(r.text_error(),None);assert!(r.text_stats().unwrap().requested_glyphs>0);
}
